add_filter( 'woocommerce_customer_taxable_address', 'perfectpixel_default_tax_location' );

function perfectpixel_default_tax_location( $address ) {
	// $address = array( country, state, postcode, city ).
	if ( empty( $address[0] ) ) {
		$address[0] = strtoupper( sanitize_text_field( '{{default_tax_country}}' ) );
		$address[1] = strtoupper( sanitize_text_field( '{{default_tax_state}}' ) );
	}
	return $address;
}
